#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn cancelled_cold_get_admission_does_not_hold_execution_permits() {
        use crate::http::{self, AuthConfig, Role, Token};
        use http_body_util::BodyExt;
        use tower::ServiceExt;
        let dir = tempfile::tempdir().unwrap();
        let store = Store::open(dir.path(), Options::default()).unwrap();
        let a = store.create_tenant("cold-a").unwrap().id;
        let b = store.create_tenant("cold-b").unwrap().id;
        let good = store
            .tenant(store.create_tenant("warm").unwrap().id)
            .unwrap();
        good.create_collection("docs").unwrap();
        let ack = good
            .put(
                "docs",
                serde_json::json!({"_key":"confirmed","value":7}),
                None,
            )
            .unwrap();
        store.owner.stop.store(true, Ordering::Release);
        for worker in store.owner.workers.lock().drain(..) {
            worker.join().unwrap();
        }
        let app = http::app(
            store.clone(),
            AuthConfig {
                tokens: vec![Token {
                    subject: "admin".into(),
                    sha256: http::token_hash("cold-admission-secret"),
                    tenant: None,
                    role: Role::Admin,
                }],
            },
        )
        .unwrap();
        let slots = [store.slot(a), store.slot(b)];
        let held_slots = slots.clone();
        let (entered, ready) = std::sync::mpsc::channel();
        let (release, wait) = std::sync::mpsc::channel();
        let holder = thread::spawn(move || {
            let _a = held_slots[0].lock();
            let _b = held_slots[1].lock();
            entered.send(()).unwrap();
            let _ = wait.recv_timeout(Duration::from_secs(10));
        });
        ready.recv().unwrap();
        let references = slots.each_ref().map(Arc::strong_count);
        let mut waiting = Vec::new();
        for id in [a, b] {
            for _ in 0..32 {
                let app = app.clone();
                waiting.push(tokio::spawn(async move {
                    app.oneshot(
                        axum::http::Request::builder()
                            .uri(format!("/v1/tenants/{id}"))
                            .header("authorization", "Bearer cold-admission-secret")
                            .body(axum::body::Body::empty())
                            .unwrap(),
                    )
                    .await
                    .unwrap()
                }));
            }
        }
        let deadline = Instant::now() + Duration::from_secs(3);
        while slots
            .iter()
            .zip(references)
            .any(|(slot, n)| Arc::strong_count(slot) < n + 32)
        {
            assert!(
                Instant::now() < deadline,
                "requests did not enter blocked admission"
            );
            tokio::time::sleep(Duration::from_millis(1)).await;
        }
        for request in waiting {
            request.abort();
            let _ = request.await;
        }
        let request = |uri: String| {
            axum::http::Request::builder()
                .uri(uri)
                .header("authorization", "Bearer cold-admission-secret")
                .body(axum::body::Body::empty())
                .unwrap()
        };
        let cold = app
            .clone()
            .oneshot(request(format!("/v1/tenants/{a}")))
            .await
            .unwrap();
        let healthy = tokio::time::timeout(
            Duration::from_secs(1),
            app.oneshot(request(format!(
                "/v1/tenants/{}/collections/docs/documents/confirmed",
                good.id()
            ))),
        )
        .await;
        release.send(()).unwrap();
        holder.join().unwrap();
        assert_eq!(cold.status(), axum::http::StatusCode::TOO_MANY_REQUESTS);
        let healthy = healthy.unwrap().unwrap();
        assert!(healthy.status().is_success());
        let body: serde_json::Value =
            serde_json::from_slice(&healthy.into_body().collect().await.unwrap().to_bytes())
                .unwrap();
        assert_eq!(body["_rev"], ack.rev);
    }

#[test]
    fn flush_output_overtakes_a_read_backlog_and_keeps_confirmed_data() {
        let dir = tempfile::tempdir().unwrap();
        let store = crate::Store::open(
            dir.path(),
            Options {
                io_workers: 1,
                ..Default::default()
            },
        )
        .unwrap();
        let tenant = store
            .tenant(store.create_tenant("flush-priority").unwrap().id)
            .unwrap();
        let engine = tenant.engine().clone();
        drop(tenant);
        drop(store);
        let payload = vec![42; 512 << 10];
        engine
            .transact(|tx| tx.put(b"payload".to_vec(), payload.clone()))
            .unwrap();
        let (entered, ready) = std::sync::mpsc::channel();
        let (release, wait) = std::sync::mpsc::channel();
        let blocker = engine
            .io
            .submit(engine.info.id, move || {
                entered.send(()).unwrap();
                wait.recv().unwrap();
                Ok(())
            })
            .unwrap();
        ready.recv().unwrap();
        let flushing = engine.clone();
        let flush = std::thread::spawn(move || flushing.flush());
        let deadline = Instant::now() + Duration::from_secs(3);
        while engine.view.read().frozen.is_empty() {
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        while engine.io.stats(engine.info.id)["queued_jobs"]
            .as_u64()
            .unwrap()
            == 0
        {
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        let (read_entered, read_ready) = std::sync::mpsc::channel();
        let (read_release, read_wait) = std::sync::mpsc::channel();
        let first_read = engine
            .io
            .submit_read(engine.info.id, None, false, move || {
                read_entered.send(()).unwrap();
                read_wait.recv().unwrap();
                Ok(())
            })
            .unwrap();
        let early = Arc::new(AtomicBool::new(false));
        let mut reads = Vec::new();
        for _ in 0..31 {
            let early = early.clone();
            let path = engine.path.join("sst");
            reads.push(
                engine
                    .io
                    .submit_read(engine.info.id, None, false, move || {
                        let output_written = fs::read_dir(path)?
                            .any(|p| p.is_ok_and(|p| p.metadata().is_ok_and(|m| m.len() > 64)));
                        if !output_written {
                            early.store(true, Ordering::Release);
                        }
                        Ok(())
                    })
                    .unwrap(),
            );
        }
        release.send(()).unwrap();
        blocker.wait().unwrap();
        read_ready.recv().unwrap();
        let deadline = Instant::now() + Duration::from_secs(3);
        while engine.io.stats(engine.info.id)["queued_jobs"]
            .as_u64()
            .unwrap()
            < 32
        {
            assert!(Instant::now() < deadline);
            std::thread::sleep(Duration::from_millis(1));
        }
        read_release.send(()).unwrap();
        first_read.wait().unwrap();
        flush.join().unwrap().unwrap();
        for task in reads {
            task.wait().unwrap();
        }
        assert!(
            !early.load(Ordering::Acquire),
            "queued reads overtook the flush output"
        );
        let snapshot = engine.snapshot().unwrap();
        assert_eq!(
            snapshot
                .get(b"payload", &mut ReadStats::default())
                .unwrap()
                .unwrap()
                .as_slice(),
            payload
        );
        engine.verify().unwrap();
    }

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn four_index_builds_leave_maintenance_and_lifecycle_capacity_available() {
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(dir.path(), Options::default()).unwrap();
    let mut ids = Vec::new();
    let mut release = Vec::new();
    let mut blockers = Vec::new();
    for n in 0..4 {
        let tenant = store
            .tenant(store.create_tenant(&format!("index-{n}")).unwrap().id)
            .unwrap();
        tenant.create_collection("docs").unwrap();
        ids.push(tenant.id());
        let engine = tenant.engine().clone();
        let (entered, ready) = std::sync::mpsc::channel();
        let (send, wait) = std::sync::mpsc::channel();
        release.push(send);
        blockers.push(std::thread::spawn(move || {
            engine.transact(|_| {
                entered.send(()).unwrap();
                let _ = wait.recv_timeout(std::time::Duration::from_secs(10));
                Ok(())
            })
        }));
        ready
            .recv_timeout(std::time::Duration::from_secs(1))
            .unwrap();
    }
    let healthy = store.create_tenant("healthy-maintenance").unwrap();
    let secret = "index-lifecycle-isolation-secret";
    let app = http::app(
        store,
        AuthConfig {
            tokens: vec![Token {
                subject: "admin".into(),
                sha256: http::token_hash(secret),
                tenant: None,
                role: Role::Admin,
            }],
        },
    )
    .unwrap();
    let mut builds = Vec::new();
    for id in &ids {
        let app = app.clone();
        let id = *id;
        builds.push(tokio::spawn(async move {
            call(
                &app,
                "POST",
                &format!("/v1/tenants/{id}/collections/docs/indexes"),
                Some(secret),
                json!({"name":"index","fields":[{"field":"/value"}]}),
            )
            .await
        }));
    }
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    assert!(builds.iter().all(|task| !task.is_finished()));
    let backup = call(
        &app,
        "POST",
        &format!("/v1/tenants/{}/backup", healthy.id),
        Some(secret),
        json!({}),
    )
    .await;
    let quota = call(
        &app,
        "PATCH",
        &format!("/v1/tenants/{}", healthy.id),
        Some(secret),
        json!({"memory_bytes":healthy.memory_bytes,"disk_bytes":healthy.disk_bytes}),
    )
    .await;
    let close_busy = call(
        &app,
        "POST",
        &format!("/v1/tenants/{}/close", ids[0]),
        Some(secret),
        json!({}),
    )
    .await;
    let close = call(
        &app,
        "POST",
        &format!("/v1/tenants/{}/close", healthy.id),
        Some(secret),
        json!({}),
    )
    .await;
    let delete = call(
        &app,
        "DELETE",
        &format!("/v1/tenants/{}", healthy.id),
        Some(secret),
        json!({}),
    )
    .await;
    for send in release {
        let _ = send.send(());
    }
    for blocker in blockers {
        blocker.join().unwrap().unwrap();
    }
    for build in builds {
        assert_eq!(build.await.unwrap().0, StatusCode::OK);
    }
    for response in [backup, quota, close, delete] {
        assert_eq!(response.0, StatusCode::OK, "{}", response.1);
    }
    assert_eq!(close_busy.0, StatusCode::CONFLICT, "{}", close_busy.1);
    assert_eq!(close_busy.1["error"]["code"], "BUSY");
}

#[test]
fn later_history_sweeps_seek_past_the_previously_reclaimed_identifier_tail() {
    let dir = tempfile::tempdir().unwrap();
    let store = Store::open(
        dir.path(),
        Options {
            max_scan: 8,
            ..Default::default()
        },
    )
    .unwrap();
    let t = store
        .tenant(store.create_tenant("history-tail-seek").unwrap().id)
        .unwrap();
    t.identity_initialize(&actor(), IdentityConfig::default())
        .unwrap();
    t.set_retention(60).unwrap();
    drop(store);
    let mut state = serde_json::to_value(gc::State::default()).unwrap();
    state["migration_phase"] = json!(5);
    state["swept_floor"] = json!(200);
    let collection = t
        .engine()
        .transact(|tx| {
            let c: Collection = parse(&tx.get(&named(b"C", COLLECTION))?.unwrap())?;
            tx.delete(key(KNOWLEDGE, &1u64.to_be_bytes()))?;
            put(tx, key(KNOWLEDGE, &300u64.to_be_bytes()), &Uuid::new_v4())?;
            put(tx, STATE.to_vec(), &state)?;
            tx.put(
                document_key(c.id, &format!("history:z:{:016x}", !100u64)),
                b"baseline".to_vec(),
            )?;
            tx.put(
                document_key(c.id, &format!("history:z:{:016x}", !250u64)),
                b"new baseline".to_vec(),
            )?;
            for n in 0u64..100 {
                tx.delete(document_key(c.id, &format!("history:z:{:016x}", !n)))?;
            }
            Ok(c.id)
        })
        .unwrap();
    for _ in 0..3 {
        t.retention_step().unwrap();
    }
    let snapshot = t.engine().snapshot().unwrap();
    let state: Value = parse(
        &snapshot
            .get(STATE, &mut ReadStats::default())
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert_eq!(state["swept_floor"], 300);
    assert!(
        snapshot
            .get(
                &document_key(collection, &format!("history:z:{:016x}", !100u64)),
                &mut ReadStats::default()
            )
            .unwrap()
            .is_none()
    );
    assert!(
        snapshot
            .get(
                &document_key(collection, &format!("history:z:{:016x}", !250u64)),
                &mut ReadStats::default()
            )
            .unwrap()
            .is_some()
    );
}

#[test]
fn physical_gc_page_observes_deletions_staged_in_the_same_transaction() {
    let (_dir, store, t) = setup();
    drop(store);
    t.engine()
        .transact(|tx| {
            put(tx, key(KNOWLEDGE, &1u64.to_be_bytes()), &Uuid::new_v4())?;
            put(tx, key(KNOWLEDGE, &2u64.to_be_bytes()), &Uuid::new_v4())
        })
        .unwrap();
    t.engine()
        .transact(|tx| {
            tx.delete(key(KNOWLEDGE, &1u64.to_be_bytes()))?;
            let (rows, exhausted) = tx.gc_prefix(KNOWLEDGE, None, 8)?;
            assert!(exhausted);
            assert_eq!(rows.len(), 2);
            assert!(rows[0].value.is_none());
            assert!(rows[1].value.is_some());
            Ok(())
        })
        .unwrap();
}
